import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { test } from 'node:test';
import {
	AUTH_ROWS_SQL,
	migrationSQL,
	migrationVersion,
	schemaListProblems,
	UNBACKED_COUNTS_SQL
} from './migration.ts';

const SQL = migrationSQL(
	['app', 'app_history'],
	'npm exec --no -- supabase-backup migration --schemas app,app_history',
	'local'
);

test('migrationSQL carries the header, the list, and per-schema grants in order', () => {
	assert.ok(
		SQL.startsWith(
			'-- Generated by supabase-backup local: npm exec --no -- supabase-backup migration --schemas app,app_history.\n'
		)
	);
	assert.ok(SQL.includes(`as $$ select array['app', 'app_history']::text[] $$;`));
	assert.ok(SQL.includes(`if s <> all (array['app', 'app_history']::text[])`));
	const order = [
		'create role backup_reader nologin bypassrls',
		'alter role backup_reader bypassrls connection limit 3',
		'create schema if not exists backup',
		'grant select on supabase_migrations.schema_migrations to backup_reader',
		"to_regprocedure('backup.schemas()')",
		'create or replace function backup.schemas()',
		'grant execute on function backup.schemas() to backup_reader',
		'grant usage on schema "app" to backup_reader',
		'alter default privileges for role postgres in schema "app" grant select on sequences to backup_reader',
		'grant usage on schema "app_history" to backup_reader',
		'create or replace function backup.auth_rows()',
		'create or replace function backup.unbacked_counts()'
	].map((part) => SQL.indexOf(part));
	assert.ok(!order.includes(-1), `missing part at ${order.indexOf(-1)}`);
	assert.deepEqual(
		order,
		[...order].sort((a, b) => a - b)
	);
});

test('migrationSQL keeps the auth and coverage functions exactly as the restore expects', () => {
	assert.ok(SQL.endsWith(`${AUTH_ROWS_SQL}\n${UNBACKED_COUNTS_SQL}`));
	assert.ok(AUTH_ROWS_SQL.includes('then \'""\'::jsonb else e.value end)'));
	for (const fn of ['auth_rows', 'unbacked_counts']) {
		const body = fn === 'auth_rows' ? AUTH_ROWS_SQL : UNBACKED_COUNTS_SQL;
		assert.ok(body.includes("security definer\nset search_path = ''"));
		assert.ok(
			body.includes(
				`revoke execute on function backup.${fn}() from public, anon, authenticated, service_role;`
			)
		);
		assert.ok(body.includes(`grant execute on function backup.${fn}() to backup_reader;`));
	}
	// Security invoker, so it needs no definer review.
	assert.ok(!/create or replace function backup\.schemas\(\)[^;]*security definer/.test(SQL));
});

test('schemaListProblems refuses empty, repeated, unplain, and reserved names', () => {
	assert.deepEqual(schemaListProblems(['app', 'app_history']), []);
	assert.match(schemaListProblems([]).join(), /at least one/);
	assert.match(schemaListProblems(['app', 'app']).join(), /repeats app/);
	assert.match(schemaListProblems(['App']).join(), /plain lowercase/);
	assert.match(schemaListProblems(['public']).join(), /reserved/);
	assert.match(schemaListProblems(['pg_x']).join(), /reserved/);
	assert.match(schemaListProblems(['']).join(), /plain lowercase/);
});

test('migrationVersion is the UTC time as 14 digits', () => {
	assert.equal(migrationVersion(new Date('2026-11-02T03:04:05.678Z')), '20261102030405');
});

test('migrationSQL revokes everything from a schema dropped from the list', () => {
	for (const revoke of [
		'revoke select on tables from backup_reader',
		'revoke select on sequences from backup_reader',
		'revoke select on all tables in schema %I from backup_reader',
		'revoke select on all sequences in schema %I from backup_reader',
		'revoke usage on schema %I from backup_reader'
	]) {
		assert.ok(SQL.includes(revoke), revoke);
	}
});

test('migrationSQL names the commit it was generated by', () => {
	const sha = 'c'.repeat(40);
	assert.ok(
		migrationSQL(['app'], 'cmd', sha).startsWith(`-- Generated by supabase-backup ${sha}: cmd.\n`)
	);
});

// The restore and the shipped test expect these bodies exactly; a change must be deliberate, so update the hash with it.
test('the definer function bodies are unchanged', () => {
	const sha256 = (text: string) => createHash('sha256').update(text).digest('hex');
	assert.equal(
		sha256(AUTH_ROWS_SQL),
		'9a38fa00127f490663d1f1dea7e2d720bafb944a1398b910289ddd2ba9f9ff45'
	);
	assert.equal(
		sha256(UNBACKED_COUNTS_SQL),
		'70fca07cc0bb4e4046cadb08bc7e16da7bf5f1196ecf35eebbbc7d1824997cdc'
	);
});
